"""Bilingual teaching questions retained beside their evidence in the internal report.
Original questions are mapped in audit/QA_RESTORATION_MAP.md. No runtime claim is inferred from static code.
"""
QA = [(1, 1, 'Why use 676 training, 97 validation and 193 test rows?', '为什么采用 676 行训练、97 行验证、193 行测试？', 'The supplied 966-row protocol reserves floor(966 × 0.7) = 676 rows for training and floor(966 × 0.2) = 193 for testing. The remaining 97 form validation. Training fits weights and scaling, validation chooses checkpoints, and the final test block estimates performance after that choice. Chronological order keeps later observations out of earlier training. This is the declared project protocol, not a universal journal requirement. The independently pinned upstream split is still unverified.', '所附 966 行协议把 floor(966 × 0.7) = 676 行分给训练，floor(966 × 0.2) = 193 行分给测试，其余 97 行用于验证。训练段拟合权重和标准化参数，验证段选择检查点，最终测试段评价选择后的表现。按时间先后划分，可以避免用后来的观测训练较早的预测。这是本项目采用的协议，并非所有期刊统一要求；固定版本上游协议仍待独立核实。', 'configs.py DATA_PROFILES[author_repo_966]; BENCH_MSE_BY_MODEL_L.csv; eval_windows.py'), (2, 1, 'Why score 160 windows when 170 are available at L24?', 'L24 明明有 170 个窗口，为什么只评 160 个？', 'The local evaluation contract preserves complete batches of 16: (W//16)×16. Thus 170/158/146/134 available windows become 160/144/144/128 scored windows at L24/36/48/60. Using the same retained windows across models prevents a comparison of different test examples. Cropping can nevertheless change scores by removing a particular tail of time. It is a comparability choice inherited by this snapshot, not evidence that cropping is scientifically optimal. Full-window sensitivity remains necessary; a specific discarded-tail difficulty ratio was not independently reverified.', '本地评测约定只保留完整的 16 个窗口一批，即 (W//16)×16。因此 L24/36/48/60 的 170/158/146/134 个可用窗口变成 160/144/144/128 个计分窗口。所有模型使用相同窗口，可避免拿不同测试样本比较。但裁剪会删去某一段时间尾部，仍可能改变分数。这是本快照为保持可比性采用的选择，不证明裁剪在科学上最优；仍需完整窗口敏感性分析。本次没有独立复核某个被删尾部的具体难度倍数。', 'BENCH_MSE_BY_MODEL_L.csv; eval_windows.py; scripts/verify_snapshot.py --raw-smoke'), (3, 1, 'Why fit scaling on training data only?', '为什么标准化参数只能从训练段计算？', 'A mean or standard deviation fitted on the complete series would use information from the future test block. Train-only scaling keeps that information out of model preparation. Each channel is standardised separately. The local equality check compares seven matching numeric columns in the two supplied files and finds maximum absolute difference zero. That verifies numeric equality of these local copies, not byte identity with a newly downloaded author file.', '如果用完整序列计算均值或标准差，就会把未来测试段的信息带入模型准备过程。只在训练段拟合，可避免这类信息泄漏。七个通道分别标准化。本次一致性检查比较所附两个文件的七个对应数值列，最大绝对差为零。这只能核实本地副本数值一致，不能代替重新下载作者文件后核实字节一致。', '06_原始数据集/scaler_miflu_author966.json; scripts/verify_snapshot.py'), (4, 2, 'Why ten reproduction seeds but three benchmark seeds?', '为什么复现用十个种子，基准却用三个种子？', 'They answer different questions. The supplied reproduction uses seeds 2021–2030 to compare with the transcribed paper table. The broader benchmark uses 42/43/44 to compare implementations under one shared protocol. The retained matrix is 28 models × 4 horizons × 3 seeds = 336 cells. Ten seeds would require 1,120 cells. Three reflects the project compute budget; it does not prove adequate power, and additional seeds can improve uncertainty estimation. Neither a universal three-seed venue rule nor zero benefit from more seeds is established.', '两者回答不同问题。所附复现以 2021–2030 十个种子对照转录的原文表格；更广的基准以 42/43/44 三个种子在统一协议下比较各实现。正式矩阵为 28 模型 × 4 跨度 × 3 种子 = 336 单元；十个种子则需要 1,120 单元。采用三个种子反映项目算力预算，不证明检验功效已经足够，更多种子也可能改善不确定性估计。本次没有证据支持所有场合均要求三个种子，或增加种子毫无收益。', 'ESSAY_VS_REPRODUCTION_TABLE_V.csv; BENCH_MSE_BY_MODEL_L.csv; dlv/data.py ORACLE'), (5, 2, 'Which implementation differences are established?', '哪些实现差异已经核实，哪些仍只是待核实的说法？', 'The local code selects checkpoints on validation and scores all seven standardised channels. Supplied notes attribute test-selected checkpoints and a one-channel loader to upstream code, but no independently inspected pinned author checkout supports that attribution here. Notes also describe differences in learning-rate and epoch settings. Consequently we disclose the local procedure and unresolved reference settings rather than claiming that exactly two repairs explain every score difference. A fair causal comparison would hold data, seeds and all other settings fixed while changing one factor.', '已检查的本地代码在验证段选择检查点，并对七个标准化通道计分。交接笔记把测试集选检查点和单通道加载问题归于上游代码，但本次没有独立检查到固定版本作者仓库来支持该归因。笔记还提到学习率和训练轮数设置差异。因此应披露本地流程与未核实的参考设置，不能声称只有两处修复就解释全部分数差异。若要确认因果，应固定数据、种子及其他设置，每次只改变一个因素。', 'train_miflu.py; audit/REPO_AUDIT.md; audit/UNVERIFIED_ITEMS.md'), (6, 2, 'Why use seven-variable MSE but ILITOTAL peak errors?', '为什么 MSE 用七变量，而峰值误差只用 ILITOTAL？', 'Seven-variable MSE averages squared errors after each channel has been standardised, so it measures overall dimensionless forecast error. This average loss is not itself a patient-count time series and has no single inverse scaler. Peak timing and height require an actual series. We therefore compute them on ILITOTAL after its own training-fit inverse transform, with mean 9,439.84 and standard deviation 9,003.15 patients. A model can do well across seven channels while having worse ILITOTAL peaks. Different targets and loss functions help explain the different rankings.', '七变量 MSE 先逐通道标准化，再平均平方误差，衡量整体无量纲预测误差。这个平均损失不是患者人数时间序列，也没有一个统一的反标准化器。峰值时间与高度则必须针对一条真实序列。因此本项目对 ILITOTAL 使用其训练段标准化参数反变换，均值为 9,439.84、标准差为 9,003.15 人。一个模型可以在七通道总体误差上较好，但在 ILITOTAL 峰值上较差。评价对象与损失函数不同，是排名变化的一个解释。', 'BENCH_MSE_BY_MODEL_L.csv; BENCH_PTE_PIE_BY_STEP.csv; scaler_miflu_author966.json'), (7, 3, 'Why is MIFlu 1.4995 here but 1.5574 in the benchmark?', '为什么这里的 MIFlu 是 1.4995，基准表却是 1.5574？', 'The first is the four-horizon mean from the ten-seed reproduction table. The second is the four-horizon mean under the three benchmark seeds. They summarise separate run sets. Compare 1.4995 with the reported paper mean 1.4355 for reproduction, and compare 1.5574 with other models in the benchmark for model selection. Their difference is not a demonstrated improvement, degradation or transcription error between two otherwise identical experiments. Full run configuration and raw provenance are required to attribute it.', '前者来自十种子复现表的四跨度均值，后者来自三个基准种子的四跨度均值，它们汇总的是不同运行集合。讨论复现时，应把 1.4995 与原文转录均值 1.4355 比较；讨论选模时，应把 1.5574 与同一基准中的其他模型比较。两数之差并不能证明在其他条件完全一致时模型进步、退步或抄错；归因还需要完整运行配置与原始来源。', 'ESSAY_VS_REPRODUCTION_TABLE_V.csv lines 2–6; BENCH_MSE_BY_MODEL_L.csv model=miflu'), (8, 3, 'Why do MSE and MAE give different sign patterns?', '为什么 MSE 与 MAE 的逐跨度方向不完全一致？', 'MSE squares errors and gives larger errors more weight. MAE averages absolute errors. Changing a few large errors can therefore alter MSE and MAE differently. Relative to the paper values, MSE is lower at L24/L36 and higher at L48/L60, whereas MAE is lower only at L36 and higher at the other three. The means are +4.5% MSE and +7.9% MAE. Calling both a two-versus-two crossover would misread the table.', 'MSE 对误差平方，因此更重视大误差；MAE 平均绝对误差。因此，少数大误差的变化可能对两者产生不同影响。相对原文转录值，MSE 在 L24/L36 较低、L48/L60 较高；MAE 只有 L36 较低，其他三个跨度较高。平均差为 MSE +4.5%、MAE +7.9%。不能把两者都说成两低两高。', 'ESSAY_VS_REPRODUCTION_TABLE_V.csv lines 2–6'), (9, 3, 'Do the seed oracle and plots prove a complete reproduction?', '种子 oracle 和预测曲线能证明已完整复现吗？', 'The oracle is a code-transcribed record of ten seed scores. Its means and standard deviations can be checked arithmetically, but the corresponding raw ten-seed logs and predictions are not supplied for independent rescoring. The imported plots illustrate the benchmark series and are not independent traces of those ten reproduction runs. Checkpoint choice, seed variability and configuration differences are possible explanations for the horizon pattern, not isolated causal findings. The defensible result is a +4.5% mean-MSE gap under disclosed limits.', 'oracle 是代码中转录的十种子分数记录，可以核算均值和标准差，但没有提供对应十种子的原始日志与预测供独立重评分。沿用曲线展示基准序列，不是这些十种子复现运行的独立轨迹。检查点选择、种子波动和配置差异都可能解释逐跨度表现，但尚未分离其因果作用。可辩护的结果是在明确限制下，平均 MSE 差为 +4.5%。', 'dlv/data.py ORACLE; ESSAY_VS_REPRODUCTION_TABLE_V.csv; figure_captions.json'), (10, 4, 'What do the 28 models and different subsets mean?', '28 个模型与不同分析子集各指什么？', 'The retained roster is 13 conventional + 4 LLM-based + 11 frozen encoders. Accuracy and peak analysis cover all 28. Parameter exports support 11 arms, while paired tests cover 17 non-encoder models including MIFlu. DLinear is excluded from the retained roster and paired table by project choice. Its appearance in historical provenance does not make it a retained arm. A sensitivity analysis including DLinear would strengthen baseline coverage; prior appearance in the source paper is not by itself a scientific reason to omit it.', '正式名单为 13 个传统模型 + 4 个基于 LLM 的模型 + 11 个冻结编码器。精度和峰值分析覆盖全部 28 个；参数导出支持其中 11 个；配对检验覆盖包括 MIFlu 的 17 个非编码器模型。项目主动把 DLinear 排除于正式名单及配对表。它在历史硬件来源表中出现，不代表属于正式保留模型。补充含 DLinear 的敏感性分析可加强基线覆盖；它曾出现在原文，本身不足以构成科学排除理由。', 'BENCH_MSE_BY_MODEL_L.csv; BENCH_EFFICIENCY.csv; BENCH_PAIRED_TESTS.csv; BENCH_GPU_PROVENANCE.csv'), (11, 4, 'Does the lowest MSE make MIFlu the deployment winner?', 'MIFlu 的 MSE 最低，是否就应直接选它部署？', 'MIFlu has the lowest observed benchmark MSE, 1.5574. That is a descriptive accuracy result under one national split. It does not measure the cost of missed peaks, false alarms, runtime, regional robustness or prospective benefit. The larger MSE spread also does not establish that hyperparameter tuning is unimportant, because tuning was not experimentally varied as an alternative factor. The later evaluation axes ask additional questions that the accuracy table alone cannot answer.', 'MIFlu 的观测基准 MSE 最低，为 1.5574。这是在单一全国划分下的描述性精度结果，没有直接测量漏峰、误报、运行时间、区域稳健性或前瞻效益。MSE 差距较大，也不能证明调参不重要，因为本实验没有把调参作为另一因素进行对照。后面的评价维度回答精度表单独无法回答的问题。', 'BENCH_MSE_BY_MODEL_L.csv; audit/GRADE_READINESS.md'), (12, 5, 'Why do MIFlu and NLinear both pass 4/16?', '为什么 MIFlu 和 NLinear 都通过 4/16，却仍有不同结论？', 'A pass requires mean PTE ≤ 1 week and mean PIE ≤ 25% in the same (L, step) cell. NLinear passes step 0 at all four horizons. MIFlu passes step 0 at L24/L36/L60 and step 1 at L48. Equal counts therefore hide different locations and error magnitudes. Across all 16 cells, NLinear has lower PIE, 9.477% versus 26.846%, while MIFlu has lower PTE, 1.128 versus 1.677 weeks. The result is a timing–height trade-off, not dominance by either model.', '一次通过要求同一个（L，step）单元的平均 PTE ≤ 1 周且平均 PIE ≤ 25%。NLinear 在四个跨度的 step 0 均通过；MIFlu 在 L24/L36/L60 的 step 0，以及 L48 的 step 1 通过。因此，相同通过数会隐藏达标位置及误差大小的差异。跨全部 16 单元，NLinear 的 PIE 更低，为 9.477% 对 26.846%；MIFlu 的 PTE 更低，为 1.128 对 1.677 周。结论是时间与峰高之间存在取舍，任何一个都不是全面占优。', 'BENCH_PTE_PIE_BY_STEP.csv model in {miflu,nlinear}'), (13, 5, 'Does 4/16 mean a 25% chance of a correct epidemic forecast?', '4/16 是否表示预测流行季成功的概率为 25%？', 'No. The denominator is four horizons times four fixed forecast steps, not 16 independent seasons. Each cell already averages errors across the available runs/events. Applying thresholds after averaging can give a different answer from counting individual successful events. The separate timing and intensity tolerances are supported by Kramer–Shaman [2]; our conjunction on aggregated cells and detector settings are project choices. They are not a clinical acceptance test or a calibrated probability.', '不是。分母是四个跨度乘四个固定预测步，不是 16 个独立流行季。每个单元本身已经聚合可用运行或事件的误差。先平均再应用阈值，与先判断每个事件成功再计数，可能得到不同结果。Kramer–Shaman [2] 支持分别采用时间和强度容差；把两者联合用于聚合单元，以及具体峰检测设置，属于本项目选择，不是临床接受检验或经校准的概率。', 'BENCH_PTE_PIE_BY_STEP.csv; Kramer–Shaman [2]; analysis peak detector settings'), (14, 5, 'Why can peak rankings differ without proving decoupling?', '为什么峰值排名会改变，却不能说已经证明脱钩？', 'The leading-three MSE order is MIFlu < PatchTST < NLinear; the PIE order is NLinear < MIFlu < PatchTST. Ordering is inverted at both ends, with different middle positions. Across all models, MSE–PIE correlation is positive (+0.736) and MSE–pass-count correlation negative (−0.429), both in the expected direction for generally better error. A local rank mismatch can coexist with those overall associations. We can claim that objectives change the ordering, not statistical independence or universal peak failure.', '前三模型的 MSE 顺序为 MIFlu < PatchTST < NLinear，PIE 顺序为 NLinear < MIFlu < PatchTST。排序在两端倒置，中间位置也不同。跨全部模型，MSE–PIE 为正相关（+0.736），MSE–通过数为负相关（−0.429），都符合整体误差越低通常峰值表现越好的方向。局部排名不一致可以与整体相关同时存在。因此可主张评价目标改变排序，不能主张统计独立或所有模型都无法预测峰值。', 'BENCH_MSE_BY_MODEL_L.csv joined to BENCH_PTE_PIE_BY_STEP.csv; audit/verified_facts.json'), (15, 6, 'How should I explain the Pareto graph?', '我该怎样向导师解释 Pareto 图？', 'The horizontal axis is parameter count and the vertical axis is MSE, so smaller values are preferred on both. A model is dominated within the measured subset if another has no more parameters and no higher MSE, with at least one strict improvement. The exported frontier contains NLinear and PatchTST: NLinear is smaller, while PatchTST has lower MSE. Neither dominates the other. This frontier covers only the 11 arms with parameter exports; MIFlu and the encoders are outside it, so a global frontier claim is unsupported.', '横轴是参数量，纵轴是 MSE，两者均偏向越小越好。如果子集中另一个模型的参数不更多、MSE 不更高，且至少一项严格更好，前者就受到支配。导出的前沿包含 NLinear 和 PatchTST：NLinear 更小，PatchTST 的 MSE 更低，因此互不支配。这个前沿只覆盖有参数导出的 11 个模型，MIFlu 与冻结编码器不在其中，不能称为全部模型的全局前沿。', 'BENCH_EFFICIENCY.csv; fig_pareto_frontier.png'), (16, 6, 'Does 211 times more parameters mean 211 times slower?', '参数多 211 倍，是否就慢 211 倍？', 'No. 531,878 / 2,520 = 211.1 compares exported PatchTST and NLinear parameter counts. Their observed MSE reduction is (1.871583 − 1.662078) / 1.871583 ≈ 11.2%. Parameter storage, operations, hardware utilisation and batch size affect runtime differently. Latency, peak memory and energy require direct comparable measurements. We use the phrase parameter efficiency, and leave missing parameter counts missing rather than treating them as zero or describing MIFlu as non-parametric.', '不是。531,878 / 2,520 = 211.1 比较的是导出的 PatchTST 与 NLinear 参数量。其观测 MSE 降幅为 (1.871583 − 1.662078) / 1.871583 ≈ 11.2%。参数存储、运算、硬件利用率及批量大小对运行时间有不同影响。延迟、峰值内存与能耗需要直接且可比的测量。因此使用“参数效率”这个表述；缺失参数继续记为缺失，不能当成零，更不能把 MIFlu 描述成无参数模型。', 'BENCH_EFFICIENCY.csv; BENCH_MSE_BY_MODEL_L.csv model in {nlinear,patchtst}'), (17, 6, 'What does R squared of 0.0223 actually mean?', 'R² = 0.0223 实际说明什么？', 'For the chosen fit of MSE against log10(parameter count) in 11 exported arms, parameter size alone accounts for little observed variation. This descriptive association does not isolate the effect of capacity: architectures, optimisation and training regimes also vary. A low R squared does not prove that capacity is irrelevant or that an observed accuracy gain is random noise. A causal capacity study would vary size within a controlled family and training protocol.', '在有参数导出的 11 个模型中，以 MSE 对 log10(参数量) 拟合，参数规模单独解释的观测变化很少。这种描述性关联没有隔离容量作用，因为架构、优化与训练设置也同时不同。较低 R² 不能证明容量不重要，更不能证明观测精度增益只是随机噪声。若要研究容量因果作用，需要在受控模型家族及训练协议内改变规模。', 'BENCH_EFFICIENCY.csv; scripts/verify_snapshot.py linregress'), (18, 7, 'Why does the paired table contain seemingly unrelated model pairs?', '为什么配对检验表里会出现看起来不相关的模型对？', 'The report deliberately shows the NLinear–PatchTST frontier comparison first, followed by six rows with the smallest raw p-values. This combines the question of interest with examples of the wider test family. The frontier pair is 117th by ascending raw p in the exported table, so an automatic smallest-six display would omit it. The full family still contains all 136 comparisons; displayed-row selection never changes the Holm family or makes the selected pair significant.', '报告有意把 NLinear–PatchTST 这对前沿比较放在第一行，再列原始 p 最小的六行，这样既展示核心问题，也展示更大检验族中的例子。该前沿对在导出表按原始 p 升序排列时位于第 117，因此自动只取最小六项会漏掉它。但完整检验族仍含全部 136 对；选择展示哪几行，不能改变 Holm 校正的检验族，更不能让选中比较变显著。', 'BENCH_PAIRED_TESTS.csv model_a=nlinear/model_b=patchtst; audit/verified_facts.json pair_raw_rank'), (19, 7, 'Why do 128 raw significant pairs become zero after Holm?', '为什么未校正有 128 对显著，Holm 后却是零？', 'Testing many pairs increases the opportunity for false positives. Proper Holm sorts raw p-values and applies a forward cumulative maximum to the ordered multiplicity factors. The original exported column used the wrong direction and is quarantined. Recomputing all 136 gives 0/136 rejections, with minimum adjusted p about 0.0664 and NLinear–PatchTST 0.1172. With the documented two-sided exact n=12 resolution, the smallest possible raw p is 2/4096, already too large for Holm’s first 0.05/136 threshold. Dependence between horizon–seed cells is an additional concern.', '同时检验很多模型对会增加误报机会。正确 Holm 先排列原始 p，再按递减多重比较因子计算并取前向累计最大值。原导出列方向错误，因此保留作来源记录但不使用。重算全部 136 对后为 0/136 个拒绝，最小校正 p 约 0.0664，NLinear–PatchTST 为 0.1172。在已记录的双侧精确 n=12 分辨率下，原始 p 最低为 2/4096，已高于 Holm 第一步的 0.05/136 阈值。跨度–种子单元之间的依赖还带来另一层限制。', 'BENCH_PAIRED_TESTS.csv p_raw; analysis_postprocess.py; audit/HOLM_RECOMPUTATION.csv'), (20, 7, 'Does p = 0.1172 show that NLinear and PatchTST are equivalent?', 'p = 0.1172 是否说明 NLinear 与 PatchTST 等价？', 'No. PatchTST retains 11.2% lower observed mean MSE and lower error in 10/12 matched cells. Non-rejection means this familywise procedure does not establish a difference at the chosen threshold. It does not establish a small enough difference for practical equivalence. Equivalence needs a prespecified acceptable margin and a suitable uncertainty/test design. The table’s source effect also uses pooled model standard deviation rather than paired-difference standard deviation, so it is labelled as a source standardised effect.', '不是。PatchTST 的观测平均 MSE 仍低 11.2%，且在 10/12 个配对单元中误差更低。未拒绝只表示该检验族校正流程没有在选定阈值下确立差异，不表示差异已小到可视为实际等价。等价判断需要预先规定可接受差异界值，并采用适合的不确定性与检验设计。表中源效应量还使用模型合并标准差，而非配对差标准差，因此只能标成源标准化效应。', 'BENCH_EFFICIENCY.csv; BENCH_PAIRED_TESTS.csv; audit/CLAIM_AUDIT.md C3'), (21, 8, 'What can the frozen-encoder negative result explain?', '冻结编码器的负面结果能解释到哪一步？', 'The tested pipeline freezes a language encoder and trains a linear readout. Its 11 encoder arms have MSE 4.7374–5.2049, all above decision tree 4.3198, with 0/16 joint passes each. This shows poor performance of these feature/readout configurations on this protocol. Distribution mismatch, frozen features and readout capacity are possible mechanisms, but the experiment does not separate them. Generation, prompting, fine-tuning and numerically pretrained time-series foundation models remain outside this test.', '所测流程冻结语言编码器，再训练线性读出。11 个编码器的 MSE 为 4.7374–5.2049，均高于决策树的 4.3198，各自通过 0/16 联合单元。这说明这些特征与读出配置在当前协议中表现较差。分布不匹配、冻结特征和读出能力都可能解释结果，但实验没有分离其作用。生成、提示、微调及数值预训练时序基础模型均不属于这项测试。', 'BENCH_MSE_BY_MODEL_L.csv family=llm_encoder; BENCH_PTE_PIE_BY_STEP.csv'), (22, 9, 'Why might no-text give identical outputs in the default path?', '为什么默认路径下去掉文本可能得到完全相同的输出？', 'In the inspected author_faithful path, time tokens precede text tokens. Causal attention permits each position to read only its own or earlier positions, and the head reads the time-token positions. Those positions therefore cannot use later text in a deterministic evaluation forward pass. The supplied archive explicitly asserts text invariance and matched-initialisation full/no-text CPU equality, and the supplied JUnit now records those three fixed-weight CPU model assertions passed with zero skips; this review did not rerun them. Other fusion paths, dropout and independently trained trajectories require separate checks. The exact files and commands are in audit/NO_TEXT_VERIFICATION.md.', '已检查的 author_faithful 路径把时间词元放在文本词元前。因果注意力只允许每个位置读取自身或更早位置，预测头又只读取时间词元位置。因此在确定性评估前向过程中，这些位置无法利用后面的文本。所附归档明确断言文本不变性，以及匹配初始化的完整/无文本 CPU 输出相同，所附 JUnit 现记录三项固定权重 CPU 模型断言通过、零跳过；本次审阅未重跑它们。其他融合路径、dropout 和独立训练轨迹仍需分别检查。精确文件与命令见 audit/NO_TEXT_VERIFICATION.md。', 'miflu_model.py ForecastingLLM; tests_archive/test_miflu_ablations.py; audit/NO_TEXT_VERIFICATION.md'), (23, 9, 'What does 60/60 ablation completion allow us to say?', '消融完成 60/60，究竟可以说什么？', 'It is queue-completion evidence in the returned 4 November records, not an aggregated model comparison or an independently rerun ablation study. The additional design has five arms, each with four horizons and three seeds: 60 cells beyond the 12-cell reference. Without per-arm result exports, completion is not evidence of a depth trend or a benefit of LoRA. Do not infer a completed no-text ablation from the presence of its test assertions. We need run-level outputs, status and provenance before reporting scientific results.', '这是 11 月 4 日回传记录中的队列完成证据，不是已聚合的模型比较，也不是本次独立重跑的消融研究。新增设计有五个变体，每个四跨度、三种子，合计 60 单元；参考模型另有 12 单元。没有逐变体结果导出，就不能从完成数量推断深度趋势或 LoRA 收益。存在 no-text 测试断言，也不代表已完成相应消融实验。报告科学结果前，需要逐运行输出、状态及来源。', 'Owner snapshot; ablation design table; tests_archive/test_miflu_ablations.py'), (24, 10, 'What is added beyond reproduction, and why keep O1?', '除了复现，本项目增加了什么，为什么默认仍选 O1？', 'The study compares implementations across accuracy, peak skill, parameter efficiency and statistical evidence, with different declared subsets. We have not verified that the reference paper contains only the first two axes, so absence or first-ever claims are inappropriate. O1 develops this evaluation contribution through provenance repair, restored tests, rolling origins, regions and stronger controls. Optional O2 is validation-only peak-height recalibration: zero new GPU training if auditable validation/test predictions already exist. Such validation exports are not established here; CPU time and money are unmeasured, and a few working days is only a planning estimate.', '本项目在明确不同子集的前提下，从精度、峰值技巧、参数效率和统计证据四个维度比较实现。本次没有核实参考论文是否只有前两项，因此不能断言原文缺失某项或声称首次发现。O1 通过补齐来源、恢复测试、滚动原点、区域和更强对照来发展实证贡献。可选 O2 是只在验证数据拟合的峰高再校准：若已有可审计的验证/测试预测，可不新增 GPU 训练。但本快照尚未确立这些验证导出；CPU 时间和费用未测量，几个工作日也仅为规划估计。', 'audit/INNOVATION_DECISION.md; audit/LITERATURE_REVIEW.md; sources.json [1]'), (25, 11, 'What can a supervisor reproduce now, and what remains unexecuted?', '导师现在能复核什么，还有什么未执行？', 'The documented CPU commands reproduce CSV headline arithmetic, correct Holm and one raw prediction-cell MSE. Seven new CPU audit checks passed. Whole-archive collection still failed. The supplied JUnit records three fixed-weight CPU no-text assertions passed with zero skips, while returned core artefacts satisfy 160/160 completeness checks. The national 1120 matrix remains in progress. Full common-panel scoring, pinned upstream identity and independent-training text effects remain unresolved; this review did not rerun GPU training or connect to live HPC. Hardware provenance also lacks complete retained-cell coverage. A polished document does not close those gaps. Use the exact follow-up commands in audit/EXECUTION_STATUS.md and audit/NO_TEXT_VERIFICATION.md.', '文档中的 CPU 命令可以重算 CSV 主要聚合、正确 Holm 和一个原始预测单元的 MSE；七个新增 CPU 审计检查已通过。整个历史归档的收集仍失败。所附 JUnit 记录三项固定权重 CPU no-text 断言通过且零跳过，核心产物满足 160/160 完整性检查；全国 1120 矩阵仍在进行。完整共同面板评分及固定上游身份仍待核实，本次未重跑 GPU 训练或连接实时 HPC，硬件来源也未完整覆盖正式单元。文档排版完善不能补足这些证据。精确后续命令见 audit/EXECUTION_STATUS.md 与 audit/NO_TEXT_VERIFICATION.md。', 'audit/EXECUTION_STATUS.md; audit/NO_TEXT_VERIFICATION.md; audit/REPO_AUDIT.md')]


from qa_literature import SUPPORT

def qa_blocks(ids):
    rows = []
    for qid, section, enq, zhq, ena, zha, source in QA:
        if qid in ids:
            rows += [('h3', {'en':f'Q{qid:02d} {enq}', 'zh':f'Q{qid:02d} {zhq}'}),
                     ('p', {'en':'**Answer and local evidence.** '+ena, 'zh':'**直接回答与本地证据。** '+zha}),
                     ('p', {'en':'**Paper-based reasoning.** '+SUPPORT[qid]['en'], 'zh':'**文献依据与选择理由。** '+SUPPORT[qid]['zh']}),
                     ('p', {'en':'**Say to the supervisor.** '+SUPPORT[qid]['oral_en'], 'zh':'**向导师简答。** '+SUPPORT[qid]['oral_zh']}),
                     ('p', {'en':'**Reading locator.** '+SUPPORT[qid]['locator'], 'zh':'**论文位置。** '+SUPPORT[qid]['locator']}),
                     ('p', {'en':'**Evidence.** '+source, 'zh':'**证据。** '+source})]
    return rows
